query:
CREATE TABLE IF NOT EXISTS `template_marketplace` (
  `id` int AUTO_INCREMENT PRIMARY KEY,
  `templateId` int NOT NULL,
  `publisherId` int NOT NULL,
  `title` varchar(255) NOT NULL,
  `description` text,
  `category` varchar(100),
  `tags` json,
  `thumbnailUrl` text,
  `previewData` json,
  `downloadCount` int DEFAULT 0 NOT NULL,
  `rating` decimal(2,1) DEFAULT 0,
  `ratingCount` int DEFAULT 0 NOT NULL,
  `isPublished` boolean DEFAULT true NOT NULL,
  `isFeatured` boolean DEFAULT false NOT NULL,
  `version` varchar(20) DEFAULT '1.0.0' NOT NULL,
  `createdAt` timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL,
  `updatedAt` timestamp DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL
);

CREATE INDEX `idx_marketplace_publisher` ON `template_marketplace` (`publisherId`);
CREATE INDEX `idx_marketplace_category` ON `template_marketplace` (`category`);
CREATE INDEX `idx_marketplace_published` ON `template_marketplace` (`isPublished`);
CREATE INDEX `idx_marketplace_featured` ON `template_marketplace` (`isFeatured`);
CREATE INDEX `idx_marketplace_rating` ON `template_marketplace` (`rating`);
CREATE INDEX `idx_marketplace_downloads` ON `template_marketplace` (`downloadCount`);

CREATE TABLE IF NOT EXISTS `template_reviews` (
  `id` int AUTO_INCREMENT PRIMARY KEY,
  `marketplaceId` int NOT NULL,
  `userId` int NOT NULL,
  `rating` int NOT NULL,
  `comment` text,
  `isVerified` boolean DEFAULT false NOT NULL,
  `createdAt` timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL,
  `updatedAt` timestamp DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL
);

CREATE INDEX `idx_reviews_marketplace` ON `template_reviews` (`marketplaceId`);
CREATE INDEX `idx_reviews_user` ON `template_reviews` (`userId`);
CREATE INDEX `idx_reviews_rating` ON `template_reviews` (`rating`);

